import{_ as e,o as a,c as r,a2 as n}from"./chunks/framework.il0noOp3.js";const u=JSON.parse('{"title":"Platform Engineering — enumerated source for the Platform Engineering Technical Assessment","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/platform-engineering-question-set.md","filePath":"frameworks/platform-engineering-question-set.md"}'),o={name:"frameworks/platform-engineering-question-set.md"};function d(s,t,i,l,c,m){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="platform-engineering-—-enumerated-source-for-the-platform-engineering-technical-assessment" tabindex="-1">Platform Engineering — enumerated source for the Platform Engineering Technical Assessment <a class="header-anchor" href="#platform-engineering-—-enumerated-source-for-the-platform-engineering-technical-assessment" aria-label="Permalink to &quot;Platform Engineering — enumerated source for the Platform Engineering Technical Assessment&quot;">​</a></h1><p><strong>Enumerated 2026-11-25. Verification method and limits are stated below — read them before quoting any coverage number from this page.</strong></p><p>Scout&#39;s <code>platform.engineering.yaml</code> scores the capability model behind Microsoft&#39;s <a href="https://learn.microsoft.com/en-us/assessments/86bf5228-7b58-4854-b932-ac71402e0be4/" target="_blank" rel="noreferrer">Platform Engineering Technical Assessment</a>. The assessment is mostly organisational: it asks how staff and funds are allocated to the platform, how teams find and adopt it, how policy and access are governed, how resources are provisioned, what interfaces users get, and how success is measured. This page lists the items Scout asks, and every rule in that file cites an item number from the tables below.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Assessment</td><td><a href="https://learn.microsoft.com/en-us/assessments/86bf5228-7b58-4854-b932-ac71402e0be4/" target="_blank" rel="noreferrer">Platform Engineering Technical Assessment</a> (60 minutes, multiple choice and multiple response; question text not published)</td></tr><tr><td>Framework version</td><td>Platform Engineering Capability Model on Microsoft Learn (six capabilities: investment, adoption, governance, provisioning and management, interfaces, measurement and feedback; five stages: Initial, Repeatable, Defined, Managed, Optimized). Not versioned by Microsoft, current at the extraction date</td></tr><tr><td>Extraction date</td><td>2026-11-25</td></tr><tr><td>Verification method</td><td>The assessment landing page and the platform engineering hub page were fetched in full with the Microsoft Learn MCP <code>microsoft_docs_fetch</code> tool on 2026-11-25. The six capability pages and the principles, self-service, plan and application-platform pages were read through <code>microsoft_docs_search</code> excerpts of their stage tables and key sections the same day. Every <code>collect.json</code> property an automated item reads was checked against the header contract in <code>src/collect/Invoke-Collect.ps1</code>.</td></tr></tbody></table><h2 id="the-one-thing-this-enumeration-is-not" tabindex="-1">The one thing this enumeration is NOT <a class="header-anchor" href="#the-one-thing-this-enumeration-is-not" aria-label="Permalink to &quot;The one thing this enumeration is NOT&quot;">​</a></h2><p><strong>It is not Microsoft&#39;s question list.</strong> The assessment&#39;s questions are not published; its landing page gives only the length, format and a promise of tailored recommendations. The items below are <strong>Scout&#39;s</strong> reading of the published capability model, and the <code>PLATENG-*</code> IDs are Scout&#39;s.</p><p>The model places an organization at one of five stages for each capability. A stage is a description of how the organization works, so Scout does not try to name one. Each item is instead a practice the model describes, written so it can be answered Yes, Partial or No, and the score is the share of items met, not a stage per capability.</p><p>Sources:</p><ul><li>[MODEL] <a href="https://learn.microsoft.com/platform-engineering/platform-engineering-capability-model" target="_blank" rel="noreferrer">Use the Platform Engineering Capability Model</a></li><li>[INV] <a href="https://learn.microsoft.com/platform-engineering/investment" target="_blank" rel="noreferrer">Investment: Allocate budget and demonstrate ROI</a></li><li>[ADO] <a href="https://learn.microsoft.com/platform-engineering/adoption" target="_blank" rel="noreferrer">Adoption: Services, tools, and technologies</a></li><li>[GOV] <a href="https://learn.microsoft.com/platform-engineering/governance" target="_blank" rel="noreferrer">Governance: Security and compliance policies</a></li><li>[PRV] <a href="https://learn.microsoft.com/platform-engineering/provisioning-management" target="_blank" rel="noreferrer">Provisioning and management</a></li><li>[INT] <a href="https://learn.microsoft.com/platform-engineering/interfaces" target="_blank" rel="noreferrer">Interfaces: Streamline provisioning and service requests</a></li><li>[MFB] <a href="https://learn.microsoft.com/platform-engineering/measurement-feedback" target="_blank" rel="noreferrer">Measurement and feedback: Establish feedback loops</a></li><li>[PRIN] <a href="https://learn.microsoft.com/platform-engineering/about/principles" target="_blank" rel="noreferrer">Platform engineering principles</a></li><li>[SELF] <a href="https://learn.microsoft.com/platform-engineering/about/self-service" target="_blank" rel="noreferrer">Self-service with guardrails to empower developers</a></li><li>[PLAN] <a href="https://learn.microsoft.com/platform-engineering/plan" target="_blank" rel="noreferrer">Plan and prioritize</a></li><li>[APPP] <a href="https://learn.microsoft.com/platform-engineering/application-platform" target="_blank" rel="noreferrer">Refine your application platform</a></li><li>[ENGS] <a href="https://learn.microsoft.com/platform-engineering/engineering-systems" target="_blank" rel="noreferrer">Apply software engineering systems</a></li><li>[DSS] <a href="https://learn.microsoft.com/platform-engineering/developer-self-service" target="_blank" rel="noreferrer">Design a developer self-service foundation</a></li><li>[CASE] <a href="https://learn.microsoft.com/platform-engineering/case-study" target="_blank" rel="noreferrer">Case studies: Three platform engineering implementations</a></li></ul><h2 id="how-the-items-are-answered" tabindex="-1">How the items are answered <a class="header-anchor" href="#how-the-items-are-answered" aria-label="Permalink to &quot;How the items are answered&quot;">​</a></h2><p>Most items are questions about how the organization works, which no Azure API can read. They are <strong>manual</strong> rules: Scout lists them in <code>assessment-questions.csv</code> (or <code>Export-ScoutAssessmentQuestion</code>), and a person answers <code>Yes</code>, <code>Partial</code>, <code>No</code> or <code>N/A</code>. See <a href="./../assessment/questionnaire-answers.html">Questionnaire answers</a>. Where collected Azure data bears on a question, it is attached to the item as evidence, but the answer still decides the score. Items marked ✅ are <strong>automated</strong> and <strong>gated</strong>: they run only when the resources they read exist (or the data source was collected), so an estate without them reports the item Not assessed, never Passed or Failed, and an answer file cannot override them.</p><h2 id="the-enumeration-—-36-items-across-6-areas" tabindex="-1">The enumeration — 36 items across 6 areas <a class="header-anchor" href="#the-enumeration-—-36-items-across-6-areas" aria-label="Permalink to &quot;The enumeration — 36 items across 6 areas&quot;">​</a></h2><h3 id="investment-plateng-inv-—-5-items" tabindex="-1">Investment (PLATENG-INV) — 5 items <a class="header-anchor" href="#investment-plateng-inv-—-5-items" aria-label="Permalink to &quot;Investment (PLATENG-INV) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PLATENG-INV-01</td><td>Budget and people are deliberately allocated to maintain common platform capabilities, not left to voluntary effort</td><td>❌ Manual</td><td>INV</td></tr><tr><td>PLATENG-INV-02</td><td>The platform team is run like a product team, with product management, design, research and content roles alongside engineering</td><td>❌ Manual</td><td>INV</td></tr><tr><td>PLATENG-INV-03</td><td>A product roadmap, built from requirements gathered across engineering teams, sets the scope and priorities of the platform</td><td>❌ Manual</td><td>INV, PLAN</td></tr><tr><td>PLATENG-INV-04</td><td>Return on the platform investment is shown with measures beyond delivery speed, such as developer satisfaction and business outcomes</td><td>❌ Manual</td><td>INV</td></tr><tr><td>PLATENG-INV-05</td><td>Teams outside the platform team, engineering and non-engineering, have explicit funding to contribute to the platform</td><td>❌ Manual</td><td>INV</td></tr></tbody></table><h3 id="adoption-plateng-ado-—-5-items" tabindex="-1">Adoption (PLATENG-ADO) — 5 items <a class="header-anchor" href="#adoption-plateng-ado-—-5-items" aria-label="Permalink to &quot;Adoption (PLATENG-ADO) — 5 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PLATENG-ADO-01</td><td>Engineering teams can discover the platform&#39;s services, tools and technologies from a catalogue or portal, not by word of mouth</td><td>❌ Manual — Dev Center catalogs and environment types attached</td><td>ADO, PRIN</td></tr><tr><td>PLATENG-ADO-02</td><td>The platform states the value of each capability, and teams choose it over building their own rather than because it is mandated</td><td>❌ Manual</td><td>ADO</td></tr><tr><td>PLATENG-ADO-03</td><td>Use of platform capabilities is supported by templates, documentation, support forums and a clear route to help</td><td>❌ Manual</td><td>ADO</td></tr><tr><td>PLATENG-ADO-04</td><td>Internal advocates (champions, ambassadors, developer advocates) run an internal user community around the platform</td><td>❌ Manual</td><td>ADO</td></tr><tr><td>PLATENG-ADO-05</td><td>Engineering teams can contribute fixes and features back to the platform through reviewed pull requests</td><td>❌ Manual</td><td>ADO</td></tr></tbody></table><h3 id="governance-plateng-gov-—-9-items" tabindex="-1">Governance (PLATENG-GOV) — 9 items <a class="header-anchor" href="#governance-plateng-gov-—-9-items" aria-label="Permalink to &quot;Governance (PLATENG-GOV) — 9 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PLATENG-GOV-01</td><td>Security, compliance and remediation policies are defined, centrally managed and documented for every team</td><td>❌ Manual</td><td>GOV</td></tr><tr><td>PLATENG-GOV-02</td><td>Security and compliance policies are implemented as Azure Policy assignments</td><td>✅ Azure Policy assignments (needs an Azure Policy read)</td><td>GOV, APPP</td></tr><tr><td>PLATENG-GOV-03</td><td>Assigned Azure policies are enforced rather than left in audit-only (DoNotEnforce) mode</td><td>✅ assignments with <code>enforcementMode</code> DoNotEnforce</td><td>GOV, APPP</td></tr><tr><td>PLATENG-GOV-04</td><td>Policy is managed as code: stored in version control, reviewed, tested and rolled out in rings</td><td>❌ Manual</td><td>APPP</td></tr><tr><td>PLATENG-GOV-05</td><td>Threats and policy violations are monitored, audited and corrected through a defined process</td><td>❌ Manual</td><td>GOV</td></tr><tr><td>PLATENG-GOV-06</td><td>Access to platform resources follows a formal role-based model aligned to job functions, with access provisioned through automation</td><td>❌ Manual</td><td>GOV</td></tr><tr><td>PLATENG-GOV-07</td><td>Access is granted through groups and roles rather than to many individual users</td><td>✅ role assignments to individual users, fewer than 50</td><td>GOV</td></tr><tr><td>PLATENG-GOV-08</td><td>Cost is governed: budgets exist for the subscriptions the platform serves</td><td>✅ budgets (needs a Cost Management read)</td><td>GOV</td></tr><tr><td>PLATENG-GOV-09</td><td>Data and intellectual property are governed, including classification, licensing and code ownership</td><td>❌ Manual</td><td>MODEL</td></tr></tbody></table><h3 id="provisioning-and-management-plateng-prv-—-6-items" tabindex="-1">Provisioning and management (PLATENG-PRV) — 6 items <a class="header-anchor" href="#provisioning-and-management-plateng-prv-—-6-items" aria-label="Permalink to &quot;Provisioning and management (PLATENG-PRV) — 6 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PLATENG-PRV-01</td><td>Infrastructure is provisioned from infrastructure-as-code templates, not by hand in the portal</td><td>✅ deployment records with a template hash</td><td>PRV, SELF</td></tr><tr><td>PLATENG-PRV-02</td><td>Delivery pipelines are defined as code (YAML) rather than built in the classic editor</td><td>✅ Azure DevOps pipelines defined as YAML (needs -IncludeDevOps)</td><td>PRV, ENGS</td></tr><tr><td>PLATENG-PRV-03</td><td>Provisioning requests follow a structured workflow with paved paths (golden paths) and approvals only where needed</td><td>❌ Manual</td><td>PRV</td></tr><tr><td>PLATENG-PRV-04</td><td>Provisioning is automated inside CI/CD pipelines, with governance and compliance checks built into the workflow</td><td>❌ Manual</td><td>PRV</td></tr><tr><td>PLATENG-PRV-05</td><td>Teams create standardized, preconfigured environments themselves, within controlled limits</td><td>❌ Manual — Dev Center catalogs and environment types attached</td><td>PRV, SELF</td></tr><tr><td>PLATENG-PRV-06</td><td>Resource allocation and use are visible on central dashboards, and scaling is automated from usage patterns</td><td>❌ Manual — Azure Monitor autoscale settings attached</td><td>PRV</td></tr></tbody></table><h3 id="interfaces-plateng-int-—-4-items" tabindex="-1">Interfaces (PLATENG-INT) — 4 items <a class="header-anchor" href="#interfaces-plateng-int-—-4-items" aria-label="Permalink to &quot;Interfaces (PLATENG-INT) — 4 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PLATENG-INT-01</td><td>Consistent, standard interfaces exist to provision and observe platform capabilities, with golden paths documented as templates</td><td>❌ Manual — Dev Center and project resources attached</td><td>INT</td></tr><tr><td>PLATENG-INT-02</td><td>Development environments are set up through the platform from a common path, not assembled by each team</td><td>❌ Manual — Dev Box pools attached</td><td>INT</td></tr><tr><td>PLATENG-INT-03</td><td>Tools to observe and diagnose deployed resources are provided on demand through the platform</td><td>❌ Manual — Application Insights components attached</td><td>INT</td></tr><tr><td>PLATENG-INT-04</td><td>An inventory or service catalogue lets users find assets and avoid duplicating them</td><td>❌ Manual</td><td>PRIN, DSS</td></tr></tbody></table><h3 id="measurement-and-feedback-plateng-mfb-—-7-items" tabindex="-1">Measurement and feedback (PLATENG-MFB) — 7 items <a class="header-anchor" href="#measurement-and-feedback-plateng-mfb-—-7-items" aria-label="Permalink to &quot;Measurement and feedback (PLATENG-MFB) — 7 items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Item</th><th>Scout</th><th>Source</th></tr></thead><tbody><tr><td>PLATENG-MFB-01</td><td>Platform success is measured with value-centric metrics tied to business goals, not only activity counts</td><td>❌ Manual</td><td>MFB</td></tr><tr><td>PLATENG-MFB-02</td><td>Software delivery performance of platform users (deployment frequency, lead time, change failure rate, time to restore) is measured</td><td>❌ Manual</td><td>MFB, CASE</td></tr><tr><td>PLATENG-MFB-03</td><td>User feedback is collected through structured mechanisms built into the platform, not only ad hoc</td><td>❌ Manual</td><td>MFB</td></tr><tr><td>PLATENG-MFB-04</td><td>Feedback is analysed and correlated with performance metrics to drive the platform roadmap</td><td>❌ Manual</td><td>MFB</td></tr><tr><td>PLATENG-MFB-05</td><td>Executives, platform users and product teams all take part in feedback loops</td><td>❌ Manual</td><td>MFB</td></tr><tr><td>PLATENG-MFB-06</td><td>Lessons learned and platform documentation are kept current and shared with all stakeholders</td><td>❌ Manual</td><td>MFB</td></tr><tr><td>PLATENG-MFB-07</td><td>Platform goals are set as objectives and key results (OKRs) agreed with leadership and scoped to business objectives</td><td>❌ Manual</td><td>PLAN</td></tr></tbody></table><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Items</th><th>Automated (✅)</th><th>Manual (❌)</th></tr></thead><tbody><tr><td>Investment</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Adoption</td><td>5</td><td>0</td><td>5</td></tr><tr><td>Governance</td><td>9</td><td>4</td><td>5</td></tr><tr><td>Provisioning and management</td><td>6</td><td>2</td><td>4</td></tr><tr><td>Interfaces</td><td>4</td><td>0</td><td>4</td></tr><tr><td>Measurement and feedback</td><td>7</td><td>0</td><td>7</td></tr><tr><td><strong>Total</strong></td><td><strong>36</strong></td><td><strong>6</strong></td><td><strong>30</strong></td></tr></tbody></table><p>Only six of the 36 items can be judged from Azure data, and those only partly: Azure Policy assignments and their enforcement mode, direct user role assignments, budgets, infrastructure-as-code deployment records and YAML pipelines. Azure DevOps items need <code>-IncludeDevOps</code>; Azure Policy, role assignment and budget items need those reads to have succeeded. Dev Center catalogs, Dev Box pools, Application Insights and autoscale settings are attached to some questions as evidence only, because a platform can be built on other tools and their absence proves nothing.</p>',28)])])}const p=e(o,[["render",d]]);export{u as __pageData,p as default};
